import ast, datetime, hashlib, json, subprocess
from pathlib import Path
root=Path.cwd(); d=root/'00_nucleo/diagnosticos'
def read(n): return json.loads((d/n).read_text())
def digest(p): return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def pin(p): return {'path':str(p),'sha256':digest(p),'bytes':p.stat().st_size}
def git(*a): return subprocess.check_output(['git',*a],text=True)
b=read('p1307-r2-baseline.json'); old=read('p1307-baseline.json'); pf=read('p1307-r2-preflight.json')
m=read('p1307-r2-measurement.json')['matrix']; gates=read('p1307-r2-gates.json')
checks={}
checks['head_unchanged']=git('rev-parse','HEAD')==b['state']['head']
checks['tracked_diff_unchanged']=git('diff','HEAD','--binary')==b['state']['diff']
checks['all_source_L0_Cargo_hashes_unchanged']=all(digest(root/p)==h for p,h in b['source_inventory'].items())
checks['old_P1307_artifacts_unchanged']=all(digest(r['path'])==r['sha256'] for r in b['predecessor_artifacts'].values())
checks['P1306_closure_unchanged']=all(digest(r['path'])==r['sha256'] for r in old['p1306_closure'].values())
checks['step_unchanged']=digest(old['step']['path'])==old['step']['sha256']
checks['new_preflight_and_coordinator_pins_match']=all(digest(b[k]['path'])==b[k]['sha256'] for k in ['preflight','script'])
checks['binary_pins_match']=all(digest(r['path'])==r['sha256'] for r in b['binaries'].values())
checks['matrix_dimensions']=len(m['cases'])==48 and set(m['orders'])=={'normal','repeat','reverse'} and all(len(rows)==384 for rows in m['orders'].values())
normal={(r['case'],r['profile'],r['side']):r for r in m['orders']['normal']}
checks['matrix_unique_keys']=len(normal)==384 and all(len({(r['case'],r['profile'],r['side']) for r in rows})==384 for rows in m['orders'].values())
checks['complete_output_stability']=all(all(r[k]==normal[(r['case'],r['profile'],r['side'])][k] for k in ['returncode','stdout','stderr','observable']) for rows in m['orders'].values() for r in rows)
checks['matrix_unknowns_zero']=not m['unknowns'] and all(r['observable']['kind']!='Unknown' for rows in m['orders'].values() for r in rows)
checks['context_types_really_constructed']=all(r['observable']['kind']=='transported-public-string' and r['observable']['value']==({'type-Location':'location','type-LocatedContent':'content'}[r['case']]) for r in m['orders']['normal'] if r['case'] in ('type-Location','type-LocatedContent'))
checks['feature_controls_not_ignored']=all((r['observable']['kind']=='transported-public-string' if ((r['case']=='feature-html' and r['profile'] in ('html','html+a11y')) or (r['case']=='feature-a11y' and r['profile'] in ('a11y','html+a11y'))) else r['observable']['kind']=='diagnostic') for r in m['orders']['normal'] if r['case'] in ('feature-html','feature-a11y'))
checks['CBOR_full_public_octets']=all(r['observable']['kind']=='value' and isinstance(r['observable']['value'],list) and all(type(v) is int and 0<=v<=255 for v in r['observable']['value']) for r in m['orders']['normal'] if r['case'].startswith('cbor-payload-'))
checks['partial_function_repr_retification']=all(r['observable']=={'kind':'value','value':['function','(..) => ..']} for r in m['orders']['normal'] if r['side']=='vanilla' and r['case'].endswith('encoder-with-identity'))
checks['read_only_gates_pass']=all(g['exit']==0 for g in gates if g['kind']=='read_only_gate')
checks['unstaged']=not git('diff','--cached','--name-only')
expected={'00_nucleo/diagnosticos/'+n for n in pf['outputs_exact']}
initial={line[3:] for line in b['state']['status'].splitlines() if line.startswith('?? ')}
checks['no_undeclared_files']=not (set(git('ls-files','--others','--exclude-standard').splitlines())-initial-expected)
files={}
for n in pf['outputs_exact']:
 if n=='p1307-r2-verification.json': continue
 p=d/n; text=p.read_text()
 if p.suffix=='.json': json.loads(text)
 if p.suffix=='.py': ast.parse(text)
 assert text.endswith('\n') and all(line==line.rstrip() for line in text.splitlines()),n
 files[n]=pin(p)
checks['declared_artifacts_parse_and_whitespace']=True
result={'schema':'p1307-r2-documentary-integrity-v1','at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'P1307_R2_AUDIT_COMPLETE_PUBLIC_CARRIER_SCOPE_REQUIRED','executor':'/root documentary coordinator; not a final independent implementation verifier','regime':'executado sem atestacao de isolamento tecnico','checks':checks,'consistent':all(checks.values()),'inputs':files,'state':{'head':git('rev-parse','HEAD'),'diff_stat':git('diff','HEAD','--stat'),'status':git('status','--short')},'matrix_runs':sum(map(len,m['orders'].values())),'matrix_Unknown':len(m['unknowns']),'candidate_exists':False,'L0_changed':False,'public_contract_approval_received':False,'implementation_authorized':False,'ready_encoder_seal':False,'mutation_score':None,'scope':'Verifies documentary integrity, fixed observation route and preservation of old code/evidence. Does not certify full encoder parity or approve proposed Args design.'}
print(json.dumps(result,ensure_ascii=False,indent=2))
